mapper.sql:
with tempA as ( select PORTFOLIO_ID portfolioId,max(CDATE) as maxCdate from PTL_SEC_VALUTION where 1=1
and CDATE < to_date(#{searchDate},'yyyy-mm-dd')
AND PORTFOLIO_ID IN
#{item}
group by PORTFOLIO_ID ), tempB as( select PORTFOLIO_ID portfolioId,min(CDATE) as maxCdate from PTL_SEC_VALUTION where 1=1
AND PORTFOLIO_ID IN
#{item}
and to_char(CDATE,'MM')>=TO_CHAR(to_date(#{searchDate},'yyyy-mm-dd'),'MM')
group by PORTFOLIO_ID ), tempC as( select PORTFOLIO_ID portfolioId,min(CDATE) as maxCdate from PTL_SEC_VALUTION where 1=1
and CDATE >= to_date(to_char(to_date(#{searchDate},'yyyy-mm-dd'),'yyyy')||'-01-01','yyyy-mm-dd')
AND PORTFOLIO_ID IN
#{item}
group by PORTFOLIO_ID ), assetHold as ( select A.cdate,A.portfolioId,A.portfolioName,A.finprodType2,A.type5,A.finprodMarketId,A.finprodAbbr,A.marketValue,
A.dscCostAmt, A.shareAmt, A.tdyIntincexp, ((nvl(A.marketValue, 0) + nvl(A.tdyIntincexp, 0)) / B.typeMarketValue) * 100 as tdyAmtRation, CASE WHEN to_char( A.CDATE, 'yyyy-mm-dd' ) = to_char( A.VDATE, 'yyyy-mm-dd') THEN null ELSE (((nvl(A.marketValue, 0) + nvl(A.tdyIntincexp, 0)) / B.typeMarketValue) - nvl(C.ystAmtRation, 0)) * 100 END ystAmtRation, CASE WHEN to_char( A.CDATE, 'yyyy-mm-dd' ) = to_char( A.VDATE, 'yyyy-mm-dd') THEN null ELSE (((nvl(A.marketValue, 0) + nvl(A.tdyIntincexp, 0)) / B.typeMarketValue) - nvl(D.monthAmtRation, 0)) * 100 END monthAmtRation, CASE WHEN to_char( A.CDATE, 'yyyy-mm-dd' ) = to_char( A.VDATE, 'yyyy-mm-dd') THEN null ELSE (((nvl(A.marketValue, 0) + nvl(A.tdyIntincexp, 0)) / B.typeMarketValue) - nvl(F.yearAmtRation, 0)) * 100 END yearAmtRation, C.ystAmtRation ystAmtRationTemp, D.monthAmtRation monthAmtRationExTemp, F.yearAmtRation yearAmtRationTemp, C.marketValue ystMarketValue, C.tdyIntincexp ystTdyIntincexp from ( select pp.VDATE AS vdate,psv.CDATE as cdate,psv.PORTFOLIO_ID as portfolioId,pp.PORTFOLIO_NAME as portfolioName, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*psv.TDY_INTINCEXP when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.TDY_INTINCEXP when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*psv.TDY_INTINCEXP else psv.TDY_INTINCEXP end as tdyIntincexp, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) else (NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) end as marketValue, psv.SHARE_AMT as shareAmt, fpt.TYPE_8 as finprodType2, nvl(fp.FINPROD_MARKET_ID,psv.FINPROD_ID) as finprodMarketId, NVL(fp.FINPROD_ID,psv.FINPROD_ID) AS finprodId, nvl(fp.FINPROD_ABBR, fp.FINPROD_NAME) as finprodAbbr, decode(fpt.TYPE_8,'F07',fpt.TYPE_7,'F10',fpt.TYPE_7,fpt.TYPE_6) as type5 from PTL_SEC_VALUTION psv left join FIN_PRODUCT fp on psv.FINPROD_ID=fp.FINPROD_ID left join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID left join FIN_PRODUCT_ADD fpa ON nvl(pp.PARENT_PORTFOLIO_ID,pp.PORTFOLIO_ID) = fpa.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT FP1 ON FPA.FINPROD_ID = FP1.FINPROD_ID inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null where FP1.FINPROD_TYPE2 = 'F16'
and psv.CDATE = to_date(#{searchDate},'yyyy-mm-dd')
AND psv.PORTFOLIO_ID IN
#{item}
AND fpt.TYPE_8 IN
#{item}
AND fpa.PROD_MANAGER IN
#{item}
AND (psv.DSC_COST_AMT>0 or psv.SHARE_AMT>0) ) A left join( select psv.CDATE as cdate,psv.PORTFOLIO_ID as portfolioId, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) else (nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) end ) as typeMarketValue from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null where 1=1
and psv.CDATE = to_date(#{searchDate},'yyyy-mm-dd')
AND psv.PORTFOLIO_ID IN
#{item}
group by psv.CDATE,psv.PORTFOLIO_ID ) B on A.portfolioId=B.portfolioId and A.cdate=B.cdate and B.typeMarketValue!=0 left join( select AA.cdate,AA.portfolioId,AA.finprodType2,AA.finprodId,round((nvl(AA.marketValue, 0) + nvl(AA.tdyIntincexp, 0)) / BB.typeMarketValue, 4) as ystAmtRation , AA.marketValue as marketValue, AA.tdyIntincexp as tdyIntincexp, BB.typeMarketValue as typeMarketValue from( select psv.CDATE as cdate, psv.PORTFOLIO_ID as portfolioId, psv.FINPROD_ID AS finprodId, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) else (nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) end ) as marketValue, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_INTINCEXP,0)) else (nvl(psv.TDY_INTINCEXP,0)) end ) as tdyIntincexp, fpt.TYPE_8 as finprodType2 from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null inner join tempA E on E.portfolioId=psv.PORTFOLIO_ID where psv.CDATE=E.maxCdate
AND psv.PORTFOLIO_ID IN
#{item}
AND fpt.TYPE_8 IN
#{item}
group by psv.CDATE,psv.PORTFOLIO_ID, fpt.TYPE_8, psv.FINPROD_ID )AA left join( select psv.CDATE as cdate,psv.PORTFOLIO_ID as portfolioId, /*fpt.TYPE_8 as finprodType2,*/ sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) else (nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) end ) as typeMarketValue from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null inner join tempA E on E.portfolioId=psv.PORTFOLIO_ID where psv.CDATE=E.maxCdate
AND psv.PORTFOLIO_ID IN
#{item}
group by psv.CDATE,psv.PORTFOLIO_ID /*,fpt.TYPE_8*/ )BB on AA.portfolioId=BB.portfolioId and AA.cdate=BB.cdate /*and AA.finprodType2=BB.finprodType2*/ where BB.typeMarketValue!=0 )C on A.portfolioId=C.portfolioId and A.finprodType2=C.finprodType2 and A.finprodId=C.finprodId left join( select AA.cdate,AA.portfolioId,AA.finprodType2,AA.finprodId,(nvl(AA.marketValue,0)+nvl(AA.tdyIntincexp,0))/BB.typeMarketValue as monthAmtRation from ( select psv.CDATE as cdate, psv.PORTFOLIO_ID as portfolioId, psv.FINPROD_ID AS finprodId, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) else (nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) end ) as marketValue, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_INTINCEXP,0)) else (nvl(psv.TDY_INTINCEXP,0)) end ) as tdyIntincexp, fpt.TYPE_8 as finprodType2 from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null inner join tempB E on E.portfolioId=psv.PORTFOLIO_ID where psv.CDATE=E.maxCdate
AND psv.PORTFOLIO_ID IN
#{item}
AND fpt.TYPE_8 IN
#{item}
group by psv.CDATE,psv.PORTFOLIO_ID, fpt.TYPE_8, psv.FINPROD_ID )AA left join( select psv.CDATE as cdate,psv.PORTFOLIO_ID as portfolioId, /*fpt.TYPE_8 as finprodType2,*/ sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) else (nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) end ) as typeMarketValue from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null inner join tempB E on E.portfolioId=psv.PORTFOLIO_ID where psv.CDATE=E.maxCdate
AND psv.PORTFOLIO_ID IN
#{item}
group by psv.CDATE,psv.PORTFOLIO_ID /*,fpt.TYPE_8*/ )BB on AA.portfolioId=BB.portfolioId and AA.cdate=BB.cdate /*and AA.finprodType2=BB.finprodType2*/ where BB.typeMarketValue!=0 ) D on A.portfolioId=D.portfolioId and A.finprodType2=D.finprodType2 AND A.finprodId=D.finprodId left join( select AA.cdate,AA.portfolioId,AA.finprodType2,AA.finprodId,(nvl(AA.marketValue,0)+nvl(AA.tdyIntincexp,0))/BB.typeMarketValue as yearAmtRation from ( select psv.CDATE as cdate, psv.PORTFOLIO_ID as portfolioId, psv.FINPROD_ID AS finprodId, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) else (nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)) end ) as marketValue, sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_INTINCEXP,0)) else (nvl(psv.TDY_INTINCEXP,0)) end ) as tdyIntincexp, fpt.TYPE_8 as finprodType2 from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null inner join tempC E on E.portfolioId=psv.PORTFOLIO_ID where psv.CDATE=E.maxCdate
AND psv.PORTFOLIO_ID IN
#{item}
AND fpt.TYPE_8 IN
#{item}
group by psv.CDATE,psv.PORTFOLIO_ID, fpt.TYPE_8, psv.FINPROD_ID )AA left join( select psv.CDATE as cdate,psv.PORTFOLIO_ID as portfolioId, /*fpt.TYPE_8 as finprodType2,*/ sum( case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_7 = '01' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) when fpt.TYPE_8 = 'F10' AND fpt.TYPE_7 = '03' then -1*(nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) else (nvl(psv.TDY_FLOAT_INGPL,0)+nvl(psv.DSC_COST_AMT,0)+nvl(psv.TDY_INTINCEXP,0)) end ) as typeMarketValue from PTL_SEC_VALUTION psv
inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID and fpt.TYPE_8 is not null inner join tempC E on E.portfolioId=psv.PORTFOLIO_ID where psv.CDATE=E.maxCdate
AND psv.PORTFOLIO_ID IN
#{item}
group by psv.CDATE,psv.PORTFOLIO_ID /*,fpt.TYPE_8*/ )BB on AA.portfolioId=BB.portfolioId and AA.cdate=BB.cdate /*and AA.finprodType2=BB.finprodType2*/ where BB.typeMarketValue!=0 )F on A.portfolioId=F.portfolioId and A.finprodType2=F.finprodType2 AND A.finprodId=F.finprodId union all SELECT S.cdate cdate, S.portfolioId portfolioId, S.portfolioName portfolioName, #{cash} finprodType2,#{cash} type5, NULL finprodMarketId,NULL finprodAbbr, S.marketValue marketValue, S.dscCostAmt dscCostAmt, null shareAmt, NULL tdyIntincexp, NULL tdyAmtRation, NULL ystAmtRation, NULL monthAmtRation, NULL yearAmtRation, NULL ystAmtRationTemp, NULL monthAmtRationExTemp, NULL yearAmtRationTemp, SS.marketValue ystMarketValue, NULL ystTdyIntincexp FROM( SELECT psv.cdate cdate, psv.portfolio_Id portfolioId, pp.portfolio_Name portfolioName, #{cash} finprodType2,#{cash} type5, NULL finprodMarketId,NULL finprodAbbr, pcp.amount marketValue, pcp.amount dscCostAmt, null shareAmt, NULL tdyIntincexp, NULL tdyAmtRation, NULL ystAmtRation, NULL monthAmtRation, NULL yearAmtRation, NULL ystAmtRationTemp, NULL monthAmtRationExTemp, NULL yearAmtRationTemp, NULL ystMarketValue, NULL ystTdyIntincexp ,pcp.acct_id FROM PTL_SEC_VALUTION psv LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_MARKET_ID = psv.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN PTL_PORTFOLIO pp ON psv.PORTFOLIO_ID = pp.PORTFOLIO_ID LEFT JOIN PTL_CASH_POSITION pcp ON psv.PORTFOLIO_ID = pcp.PORTFOLIO_ID and psv.cdate = pcp.cdate left JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = psv.FINPROD_ID and fpt.TYPE_8 is not null WHERE psv.CDATE = to_date(#{searchDate},'yyyy-mm-dd') and pcp.portfolio_Id is not NULL
AND pcp.PORTFOLIO_ID IN
#{item}
AND fpt.TYPE_8 IN
#{item}
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
GROUP BY psv.cdate,psv.portfolio_Id,pp.portfolio_Name,pcp.amount ,pcp.acct_id ) S LEFT JOIN ( SELECT psv.cdate cdate, psv.portfolio_Id portfolioId, pcp.amount marketValue, pcp.amount dscCostAmt ,pcp.acct_id FROM PTL_SEC_VALUTION psv LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_MARKET_ID = psv.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN PTL_PORTFOLIO pp ON psv.PORTFOLIO_ID = pp.PORTFOLIO_ID LEFT JOIN PTL_CASH_POSITION pcp ON psv.PORTFOLIO_ID = pcp.PORTFOLIO_ID and psv.cdate = pcp.cdate left JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = psv.FINPROD_ID and fpt.TYPE_8 is not null inner join tempA E on E.portfolioId=psv.PORTFOLIO_ID WHERE psv.CDATE=E.maxCdate and pcp.portfolio_Id is not NULL
AND pcp.PORTFOLIO_ID IN
#{item}
AND fpt.TYPE_8 IN
#{item}
AND FIN_PRODUCT_ADD.PROD_MANAGER IN
#{item}
GROUP BY psv.cdate,psv.portfolio_Id,pcp.amount ,pcp.acct_id ) SS ON S.portfolioId = SS.portfolioId and S.acct_id=SS.acct_id )

select.if:
select assetHold1.cdate,assetHold1.portfolioId,assetHold1.portfolioName,null finprodType2,null type5,null finprodMarketId,null finprodAbbr, sum(assetHold1.marketValue) marketValue, sum(assetHold1.dscCostAmt) dscCostAmt, sum(assetHold1.shareAmt) shareAmt, sum(assetHold1.tdyIntincexp) tdyIntincexp, 100 tdyAmtRation, 0 ystAmtRation, 0 monthAmtRation, 0 yearAmtRation, '02' hasChildren, CONCAT(nvl(assetHold1.portfolioId,'null'),'') childInfo, 'root' parentInfo, null as otherFinprodType2, assetHold1.portfolioName otherPortfolioName, assetHold1.belongInstitutionCode belongInstitutionCodeNew, SUM(assetHold1.ystAmtRationTemp) ystAmtRationTemp, SUM(assetHold1.monthAmtRationExTemp) monthAmtRationExTemp, SUM(assetHold1.yearAmtRationTemp) yearAmtRationTemp, SUM(assetHold1.ystMarketValue) ystMarketValue, SUM(assetHold1.ystTdyIntincexp) ystTdyIntincexp from ( SELECT assetHold.*, DATAINST.BELONG_INSTITUTION_CODE belongInstitutionCode FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1 group by cdate,portfolioId,portfolioName,assetHold1.belongInstitutionCode

select assetHold1.cdate,null portfolioId,null portfolioName,assetHold1.finprodType2,null type5,null finprodMarketId,null finprodAbbr, sum(assetHold1.marketValue) marketValue,
sum(assetHold1.dscCostAmt) dscCostAmt, sum(assetHold1.shareAmt) shareAmt, sum(assetHold1.tdyIntincexp) tdyIntincexp, round(sum(assetHold1.tdyAmtRation),2) tdyAmtRation, round(sum(assetHold1.ystAmtRation),2) ystAmtRation, round(sum(assetHold1.monthAmtRation),2) monthAmtRation, round(sum(assetHold1.yearAmtRation),2) yearAmtRation, '02' hasChildren, CONCAT(CONCAT(assetHold1.portfolioId,'_'),nvl(assetHold1.finprodType2,'null')) childInfo, CONCAT(nvl(assetHold1.portfolioId,'null'),'') parentInfo, assetHold1.finprodType2 as otherFinprodType2, assetHold1.portfolioName otherPortfolioName, round(SUM(assetHold1.ystAmtRationTemp),2) ystAmtRationTemp, round(SUM(assetHold1.monthAmtRationExTemp),2) monthAmtRationExTemp, round(SUM(assetHold1.yearAmtRationTemp),2) yearAmtRationTemp, SUM(assetHold1.ystMarketValue) ystMarketValue, SUM(assetHold1.ystTdyIntincexp) ystTdyIntincexp from ( SELECT assetHold.* FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1
CONCAT(nvl(portfolioId,'null'),'') = #{parentId}
